        "name": "ui-skills-improve-ui/agents/openai.yaml",
        "type": "agent",
        "mimeType": "text/yaml",
        "text": "interface:\n  display_name: Improve UI\n  short_description: Audit UI and prepare implementation plans\n  default_prompt: Use $improve-ui to audit the primary product surface, identify supported\n    UI problems, and recommend what to improve first. Don't modify anything or write plans\n    yet.\npolicy:\n  products:\n  - chatgpt\n  - codex\n  - api\n  - atlas\n  allow_implicit_invocation: true\n",
